package local.krasview.tv;
import android.app.*;
import android.view.*;
import android.widget.*;
import java.util.*;

final class FilterDialog {
    interface Apply {void apply(CatalogFilter value);}
    static void show(TvActivity host,CatalogFilter initial,List<Media.Genre> genres,Apply apply){
        CatalogFilter f=initial.copy();Dialog dialog=new Dialog(host);LinearLayout column=new LinearLayout(host);column.setOrientation(1);column.setPadding(host.d(28),host.d(24),host.d(28),host.d(24));column.setBackgroundColor(TvActivity.BG);
        TextView title=host.text("Фильтр",28,TvActivity.TEXT);column.addView(title);TextView type=host.button(""),genre=host.button(""),year=host.button(""),sort=host.button("");
        String[] types={"Всё","Фильмы","Сериалы","Аниме"},sections={"all","movie","series","anime"};
        Runnable refresh=()->{int selected=Arrays.asList(sections).indexOf(f.section);type.setText("Тип: "+types[Math.max(0,selected)]);genre.setText("Жанры: "+(f.genres.isEmpty()?"Все":android.text.TextUtils.join(", ",f.genres.values())));year.setText("Годы: "+f.years());sort.setText("Порядок: "+(f.sort.equals("top")?"Популярные за всё время":"Популярные сейчас"));};
        for(TextView b:new TextView[]{type,genre,year,sort}){b.setGravity(Gravity.CENTER_VERTICAL);b.setMaxLines(2);b.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,host.d(60));lp.topMargin=host.d(12);column.addView(b,lp);}
        type.setOnClickListener(v->{AlertDialog d=new AlertDialog.Builder(host).setTitle("Тип").setSingleChoiceItems(types,Math.max(0,Arrays.asList(sections).indexOf(f.section)),(x,index)->{f.section=sections[index];x.dismiss();refresh.run();}).setNegativeButton("Отмена",null).create();d.show();d.getListView().requestFocus();d.getListView().setSelection(Math.max(0,Arrays.asList(sections).indexOf(f.section)));});
        genre.setOnClickListener(v->{ArrayList<Media.Genre> options=new ArrayList<>();for(Media.Genre g:genres)if(f.section.equals("all")||g.sections.contains(f.section))options.add(g);String[] names=new String[options.size()];boolean[] checked=new boolean[names.length];LinkedHashMap<Integer,String> next=new LinkedHashMap<>(f.genres);for(int i=0;i<names.length;i++){names[i]=options.get(i).name;checked[i]=next.containsKey(options.get(i).id);}
            AlertDialog d=new AlertDialog.Builder(host).setTitle("Жанры").setMultiChoiceItems(names,checked,(x,index,on)->{Media.Genre g=options.get(index);if(on)next.put(g.id,g.name);else next.remove(g.id);}).setPositiveButton("Готово",(x,w)->{f.genres.clear();f.genres.putAll(next);refresh.run();}).setNeutralButton("Все жанры",(x,w)->{f.genres.clear();refresh.run();}).setNegativeButton("Отмена",null).create();d.show();d.getListView().requestFocus();d.getListView().setSelection(0);d.getListView().setOnKeyListener((view,key,event)->{if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_RIGHT){d.getButton(AlertDialog.BUTTON_POSITIVE).requestFocus();return true;}return false;});d.getButton(AlertDialog.BUTTON_POSITIVE).setOnKeyListener((view,key,event)->{if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_LEFT){d.getListView().requestFocus();return true;}return false;});
        });
        year.setOnClickListener(v->{int now=Calendar.getInstance().get(Calendar.YEAR);ArrayList<String> names=new ArrayList<>();ArrayList<int[]> ranges=new ArrayList<>();names.add("Все годы");ranges.add(new int[]{1900,now+1});for(int y=now;y>=now-4;y--){names.add(Integer.toString(y));ranges.add(new int[]{y,y});}for(int y=2020;y>=1980;y-=10){names.add(y+"–"+Math.min(y+9,now));ranges.add(new int[]{y,Math.min(y+9,now)});}names.add("До 1980");ranges.add(new int[]{1900,1979});int selected=0;for(int i=0;i<ranges.size();i++)if(f.from==ranges.get(i)[0]&&f.to==ranges.get(i)[1])selected=i;
            AlertDialog d=new AlertDialog.Builder(host).setTitle("Годы выпуска").setSingleChoiceItems(names.toArray(new String[0]),selected,(x,index)->{f.from=ranges.get(index)[0];f.to=ranges.get(index)[1];x.dismiss();refresh.run();}).setNegativeButton("Отмена",null).create();d.show();d.getListView().requestFocus();d.getListView().setSelection(selected);
        });
        sort.setOnClickListener(v->{AlertDialog d=new AlertDialog.Builder(host).setTitle("Порядок").setSingleChoiceItems(new String[]{"Популярные за всё время","Популярные сейчас"},f.sort.equals("top")?0:1,(x,index)->{f.sort=index==0?"top":"";x.dismiss();refresh.run();}).setNegativeButton("Отмена",null).create();d.show();d.getListView().requestFocus();d.getListView().setSelection(f.sort.equals("top")?0:1);});
        LinearLayout actions=new LinearLayout(host);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,host.d(52));ap.topMargin=host.d(24);column.addView(actions,ap);TextView go=host.button("Показать"),reset=host.button("Сбросить"),cancel=host.button("Отмена");
        for(TextView b:new TextView[]{go,reset,cancel}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.rightMargin=host.d(10);actions.addView(b,lp);}go.setId(View.generateViewId());sort.setId(View.generateViewId());sort.setNextFocusDownId(go.getId());go.setNextFocusUpId(sort.getId());reset.setNextFocusUpId(sort.getId());cancel.setNextFocusUpId(sort.getId());go.setOnClickListener(v->{dialog.dismiss();apply.apply(f);});reset.setOnClickListener(v->{f.genres.clear();f.from=1900;f.to=Calendar.getInstance().get(Calendar.YEAR)+1;f.section="all";f.sort="top";refresh.run();});cancel.setOnClickListener(v->dialog.dismiss());refresh.run();
        dialog.setContentView(column);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(host.d(720),-2);type.requestFocus();
    }
}
